<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany}; class Comment extends Model { protected $fillable=['proposal_id','user_id','content']; public function proposal():BelongsTo{return $this->belongsTo(Proposal::class)->withTrashed();} public function user():BelongsTo{return $this->belongsTo(User::class)->withTrashed();} public function replies():HasMany{return $this->hasMany(Reply::class);} }